// 事务生产者（Kafka Exactly-Once）
props.put("transactional.id", "my-transactional-producer");
props.put("enable.idempotence", "true"); // 事务依赖幂等

KafkaProducer<String, String> producer = new KafkaProducer<>(props);
producer.initTransactions(); // 向 Coordinator 注册

try {
    producer.beginTransaction();
    // 写入多个分区（原子）
    producer.send(new ProducerRecord<>("output-topic", key, value));
    // 将消费者 offset 也纳入事务
    producer.sendOffsetsToTransaction(offsetsMap, consumerGroupMetadata);
    producer.commitTransaction(); // 两阶段提交
} catch (ProducerFencedException e) {
    // 被新的同 transactional.id 生产者「围栏」，说明是 Zombie，停止
    producer.close();
} catch (KafkaException e) {
    producer.abortTransaction(); // 回滚
}
